/* ---------------- session room ---------------- */
const live = { on: false };
let sess = { screen: "list", student: null, session: null, students: null, sessions: null, band: null };
const kidsCol = () => collection(db, "mentor", user.uid, "students"), sessCol = () => collection(db, "mentor", user.uid, "sessions");
// Students come from two places: the Student Roster (lsStudents, so every guide starts with their band's students already
// there: id "ls-<sid>") and anyone a guide adds by hand. Consent and notes stay in the guide's private notebook.
// In a test view (the test guide), the roster is the test band's real students plus the test student.
const BAND_LABEL = { "K–1": "K to 1", "2–4": "Grades 2 to 4", "5–8": "Grades 5 to 8" };
const LABEL_BAND = { "K to 1": "K–1", "Grades 2 to 4": "2–4", "Grades 5 to 8": "5–8" };
const testView = () => window.wlRole && window.wlRole.test || null;
async function loadSess() {
  const a = await getDocs(kidsCol()), b = await getDocs(query(sessCol(), orderBy("at", "desc"), limit(400)));
  const own = {}; a.forEach(d => own[d.id] = { id: d.id, ...d.data() });
  sess.students = [];
  let roster = [];
  try { const r = await getDocs(collection(db, "lsStudents")); r.forEach(d => roster.push({ sid: d.id, ...d.data() })); } catch (e) { roster = null; }
  if (roster) {
    const tv = testView();
    // Someone a guide added by hand before the roster was connected (same band, same name or first name and last
    // initial) stays as they were, so their sessions and consent carry on, instead of showing up twice.
    const keys = n => { const w = String(n || "").toLowerCase().split(/\s+/).filter(Boolean); return w.length ? [w.join(" "), w[0] + " " + (w[1] || "").slice(0, 1)] : []; };
    const byHand = Object.values(own).filter(k => !k.id.startsWith("ls-"));
    roster.filter(x => !x.archived && (tv ? true : !x.test)).forEach(x => {
      const id = "ls-" + x.sid, mine = own[id] || {};
      const dup = !own[id] && byHand.find(k => LABEL_BAND[k.band] === x.band && keys(k.name).some(a => keys(x.name).includes(a)));
      if (dup) { dup.sid = x.sid; return; }
      sess.students.push({ consent: false, ...mine, id, sid: x.sid, name: x.name || "Student", band: BAND_LABEL[x.band] || mine.band || "", bandKey: x.band, roster: true, test: !!x.test });
      delete own[id];
    });
  }
  Object.values(own).forEach(k => sess.students.push({ ...k, bandKey: LABEL_BAND[k.band] || "" }));
  sess.students.sort((x, y) => x.name.localeCompare(y.name));
  sess.rosterOk = !!roster;
  sess.sessions = []; b.forEach(d => sess.sessions.push({ id: d.id, ...d.data() }));
}
// The band the list starts on: the guide's own (a test view's band too); All for admins and guests without one.
const myBandKey = () => { const b = window.wlBand ? window.wlBand({ all: true }) : "All"; return ["K–1", "2–4", "5–8"].includes(b) ? b : "All"; };
const shownKids = () => { const b = sess.band || myBandKey(); return sess.students.filter(k => b === "All" || k.bandKey === b || !k.bandKey); };
const weekStart = () => { const d = new Date(); d.setHours(0, 0, 0, 0); d.setDate(d.getDate() - ((d.getDay() + 6) % 7)); return d.getTime(); };
const lastOf = id => sess.sessions.find(s => s.studentId === id);
const doneThisWeek = id => { const l = lastOf(id); return !!l && l.at >= weekStart(); };
const fmtDate = ms => new Date(ms).toLocaleDateString(undefined, { month: "short", day: "numeric" });
const clock = s => String(Math.floor(s / 60)).padStart(2, "0") + ":" + String(s % 60).padStart(2, "0");
const go = (screen, extra) => { Object.assign(sess, { screen }, extra || {}); route(); };
// Persist a roster student's notebook entry (consent) the first time it changes.
const saveKid = (k, data) => setDoc(doc(kidsCol(), k.id), { name: k.name, band: k.band, created: k.created || Date.now(), ...data }, { merge: true });
// The AI review of one session (recorded, recapped or typed), with last session's plan for context.
async function analyze(s, k) {
  const prev = sess.sessions.find(x => x.studentId === k.id && x.analysis && x.id !== s.id && x.at < s.at);
  return parseJSON(await ai([{ role: "user", content: "Student age band: " + (k.band || "") + "\nSession type: " + ({ talk: "live conversation transcript", recap: "the guide's spoken recap after the session", notes: "the guide's typed notes" }[s.mode] || "the guide's notes") + (prev ? "\nLast session's plan: " + (prev.analysis.nextTime || []).join("; ") + (prev.analysis.commitments && prev.analysis.commitments.length ? "\nWhat the student said last time they would do: " + prev.analysis.commitments.join("; ") : "") : "") + "\n\nTranscript:\n" + (s.transcript || "(none)") + "\n\nGuide's own notes:\n" + (s.notes || "(none)") }], { system: D.SESSION_PROMPT, max: 1400 }));
}

